"""R08 §0.1 item 2: every report table is generated here from the persisted outputs on scratch (never typed). Writes
R08/tables/*.md (each with a provenance comment naming its source file and keys) and tables/sources.json."""
from __future__ import annotations
import glob, json, os, sys
import numpy as np, pandas as pd
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import r08_common as R8, r04_common as C4
TAB = R8.TABLES; os.makedirs(TAB, exist_ok=True); SRC = {}
def emit(name, src, lines): SRC[name] = src; open(f"{TAB}/{name}.md", "w").write(f"<!-- generated by report_tables_r08.py from {src} -->\n" + "\n".join(lines) + "\n"); print(f"wrote tables/{name}.md")
def f(x, d=3, sign=False):
    if x is None or (isinstance(x, float) and not np.isfinite(x)): return "—"
    if isinstance(x, (int, np.integer)): return f"{x:,}"
    return f"{x:+.{d}f}" if sign else f"{x:.{d}f}"
def ci(r, d=3, sign=False): return f"{f(r['value'], d, sign)} [{f(r['ci95'][0], d, sign)}, {f(r['ci95'][1], d, sign)}]"
def cmp(c): return f"{c['diff_median']:+.3f} [{c['ci95'][0]:+.3f}, {c['ci95'][1]:+.3f}] | {c['units_a_better']} / {c['units_b_better']} of {c['n_units']} | {c['sign_test_p_one_sided']:.3f}"
star = lambda u: f"{u}{' *' if u in R8.LOW_AMP else ''}"
units = list(C4.UNITS)

# ---- fixed inputs and guard (latest provenance record of each script)
provs = sorted(glob.glob(f"{R8.PROV}/*.json")); latest = {}
for p in provs:
    r = json.load(open(p)); latest[r["script"]] = r
L = ["| script | time | host / job | guard probes blocked | fixed inputs verified (files) | git HEAD |", "|---|---|---|---|---|---|"]
for s, r in sorted(latest.items()):
    fx = r.get("fixed_inputs") or {}; n = (len(fx.get("frozen_r05", {})) + len(fx.get("r06_freeze", {}).get("scripts", {})) + len(fx.get("r06_scores", {})) + len(fx.get("r07_scores", {})) + (1 if fx.get("features_v1_py") else 0) + (1 if fx.get("context_v1_parquet") else 0)) if fx else 0
    L.append(f"| {s} | {r['time']} | {r['host'].split('.')[0]} / {r.get('slurm_job') or 'login'} | {r['guard_probes_blocked']} / {r['guard_probes']} | {'yes' if fx else 'not checked'} ({n}) | {r['git_head'][:8] if r.get('git_head') else '?'} |")
emit("provenance", "provenance/*.json (r08_common.start)", L)

# ---- §1 within-site
ws = json.load(open(f"{R8.OUT_WITHIN}/scores.json")); fe = json.load(open(f"{R8.OUT_WITHIN}/feasibility.json")); pu = pd.read_csv(f"{R8.OUT_WITHIN}/per_unit.csv")
L = ["| unit | feasible pairs / total | tiles used | within-site ρ | held-out GBT_ship ρ | s_lr ρ | V2 (seed-avg) ρ | within-site − GBT_ship |", "|---|---|---|---|---|---|---|---|"]
for r in pu.itertuples(): L.append(f"| {star(r.unit)} | {r.n_pairs_feasible} / {r.n_pairs_total} | {r.n_tiles_used:,} | {f(r.within_site, sign=True)} | {f(r.GBT_ship_A_fine, sign=True)} | {f(r.ref_s_lr, sign=True)} | {f(r.V2_seedavg, sign=True)} | {f(r.within_minus_GBT_ship, sign=True)} |")
emit("within_site_per_unit", "within_site/per_unit.csv (within_site_r08.py)", L)
L = ["| unit set | n units | within-site | held-out GBT_ship | s_lr | V2 (seed-avg) | within-site − GBT_ship Δ [CI] | better / worse | p | within-site − V2 Δ [CI] | better / worse | p |", "|---|---|---|---|---|---|---|---|---|---|---|---|"]
for name, lab in (("all", "feasible units"), ("six", "low-amplitude (feasible)"), ("ten", "other ten (feasible)")):
    c = ws["median_ci"][name]; d = ws["comparisons_within_minus"][name]
    L.append(f"| {lab} | {c['within_site']['n_units']} | {ci(c['within_site'])} | {ci(c['GBT_ship_A_fine'])} | {ci(c['ref_s_lr'])} | {ci(c['V2_seedavg'])} | {cmp(d['GBT_ship_A_fine'])} | {cmp(d['V2_seedavg'])} |")
emit("within_site_summary", "within_site/scores.json:median_ci,comparisons_within_minus (within_site_r08.py)", L)
L = ["| pair | unit | tiles | 4×4-tile blocks | reasons |", "|---|---|---|---|---|"] + [f"| {r['pair']} | {r['unit']} | {r['n_tiles']} | {r['n_blocks']} | {'; '.join(r['reasons'])} |" for r in fe["infeasible"]]
L.append(f"| **total** | units without a feasible pair: {', '.join(fe['units_without_feasible_pair'])} | {len(fe['infeasible'])} of 38 pairs infeasible | | feasible pairs {len(fe['feasible_pairs'])} / 38; feasible units {len(fe['feasible_units'])} / 16 |")
emit("within_site_infeasible", "within_site/feasibility.json (within_site_r08.py)", L)

# ---- §2 importance
gr = json.load(open(f"{R8.OUT_IMP}/groups.json")); pi = json.load(open(f"{R8.OUT_IMP}/permutation_importance.json")); PI = pd.read_csv(f"{R8.OUT_IMP}/permutation_importance.csv"); dg = json.load(open(f"{R8.OUT_IMP}/dropgroup_scores.json")); rc = json.load(open(f"{R8.OUT_IMP}/refit_check.json"))
L = ["| group | n | features († = assigned by what it measures; the directive does not name it) |", "|---|---|---|"]
for g, cols in gr["groups"].items(): L.append(f"| {g} | {len(cols)} | " + ", ".join(f"{c}{'†' if c in set(gr['by_nature']) else ''}" for c in cols) + " |")
L.append(f"| **total** | {sum(len(c) for c in gr['groups'].values())} of {gr['n_features']} | other: {', '.join(gr['other']) if gr['other'] else 'none'} |")
emit("importance_groups", "importance/groups.json (importance_r08.py)", L)
groups = list(gr["groups"]); L = ["| unit | baseline ρ | " + " | ".join(groups) + " |", "|---|---|" + "---|" * len(groups)]
for u in units:
    s = PI[PI.unit == u].set_index("group"); L.append(f"| {star(u)} | {f(pi['baseline_rho'][u], sign=True)} | " + " | ".join(f(s.loc[g, 'importance'], sign=True) for g in groups) + " |")
for name, key in (("**median, six**", "median_six"), ("**median, ten**", "median_ten"), ("**median, all 16**", "median_all16")): L.append(f"| {name} | | " + " | ".join(f(pi['summary'][g][key], sign=True) for g in groups) + " |")
emit("importance_per_unit", "importance/permutation_importance.{csv,json} (importance_r08.py)", L)
emit("refit_check", "importance/refit_check.json (importance_r08.py)", ["| item | value |", "|---|---|", f"| rows compared | {rc['n_rows']:,} |", f"| max \\|refit − R05\\| (m) | {rc['max_abs_diff_m']:.2e} |", f"| rows differing by > 1e-9 m | {rc['n_rows_diff_gt_1e9']} |", f"| match within 1e-9 | {rc['match']} |"])
L = ["| unit | GBT_ship ρ | drop edge-and-validity ρ | Δ |", "|---|---|---|---|"] + [f"| {star(u)} | {f(v['GBT_ship'], sign=True)} | {f(v['dropEV'], sign=True)} | {f(v['diff'], sign=True)} |" for u, v in dg["per_unit"].items()]
for name, lab in (("all16", "all 16"), ("six", "six"), ("ten", "ten")): L.append(f"| **{lab}: median [CI]** | {ci(dg['median_ci_GBT_ship'][name])} | {ci(dg['median_ci_dropEV'][name])} | {cmp(dg['comparisons'][name])} |")
emit("dropgroup", "importance/dropgroup_scores.json (importance_r08.py)", L)

# ---- §3 field metrics
FM = pd.read_csv(f"{R8.OUT_FIELDS}/field_metrics.csv"); FM["unit_order"] = FM.unit; FM = FM.sort_values(["unit", "pair"])
L = ["| unit | pair | tiles | k | hr_res (m) | sector fraction (iso 0.056) | sector (deg) | edge ratio | RMS ≤ 3 px (m) | RMS > 10 px (m) | median A_fine (m) | p10–p90 (m) | shown window |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in FM.itertuples(): L.append(f"| {star(r.unit)} | {r.pair} | {r.n_tiles} | {r.k} | {r.hr_res:.2f} | {f(r.sector_frac_max)} | {r.sector_deg_max} | {f(r.edge_ratio, 2)} | {f(r.rms_near_m, 4)} | {f(r.rms_far_m, 4)} | {f(r.A_fine_median_m, 4)} | {f(r.A_fine_p10_m, 4)}–{f(r.A_fine_p90_m, 4)} | {'%.1f km sub, valid %.2f' % (r.window_side_m / 1000, r.window_valid_frac) if r.subwindow else 'whole'} |")
emit("field_metrics_per_pair", "fields/field_metrics.csv (fields_r08.py)", L)
L = ["| group | units / pairs | sector fraction: median over units (over pairs; pair range) | edge ratio: median over units (over pairs; pair range) | median A_fine (m): median over units (over pairs) | pairs with edge ratio > 2 | pairs with sector fraction > 0.10 |", "|---|---|---|---|---|---|---|"]
for name, sel in (("six (low-amplitude)", FM.unit.isin(R8.LOW_AMP)), ("ten (other)", FM.unit.isin(R8.OTHER)), ("EW0207", FM.unit == R8.EW_UNIT), ("all 16 units / 38 pairs", FM.unit.isin(units))):
    d = FM[sel]; um = d.groupby("unit")[["sector_frac_max", "edge_ratio", "A_fine_median_m"]].median()
    L.append(f"| {name} | {len(um)} / {len(d)} | {um.sector_frac_max.median():.3f} ({d.sector_frac_max.median():.3f}; {d.sector_frac_max.min():.3f}–{d.sector_frac_max.max():.3f}) | {um.edge_ratio.median():.2f} ({d.edge_ratio.median():.2f}; {d.edge_ratio.min():.2f}–{d.edge_ratio.max():.2f}) | {um.A_fine_median_m.median():.4f} ({d.A_fine_median_m.median():.4f}) | {int((d.edge_ratio > 2).sum())} / {len(d)} | {int((d.sector_frac_max > 0.10).sum())} / {len(d)} |")
emit("field_metrics_groups", "fields/field_metrics.csv (fields_r08.py)", L)

# ---- §4 level
LU = pd.read_csv(f"{R8.OUT_LEVEL}/level_per_unit.csv"); LC = json.load(open(f"{R8.OUT_LEVEL}/level_correlations.json")); LP = pd.read_csv(f"{R8.OUT_LEVEL}/level_per_pair.csv")
L = ["| unit | pairs | tiles | median A_fine (m) | median s_lr (m) | k (pairs) | lr_native (m) | log₂ k | A_fine / √log₂k | GBT_ship median (m) |", "|---|---|---|---|---|---|---|---|---|---|"]
for r in LU.itertuples(): L.append(f"| {star(r.unit) if r.unit != 'lu16' else 'lu16 (EW0207, separate)'} | {r.n_pairs} | {r.n_tiles:,} | {r.A_fine_median_m:.4f} | {r.s_lr_median_m:.2f} | {r.k_values} | {r.lr_native_values} | {r.log2k_median:.1f} | {r.A_norm_median:.4f} | {r.GBT_ship_median_m:.4f} |")
emit("level_per_unit", "level_geometry/level_per_unit.csv (level_geometry_r08.py)", L)
L = ["| unit | pair | tiles | median A_fine (m) | p10–p90 (m) | median s_lr (m) | k | lr_native (m) | hr_res (m) | log₂ k | effective octaves log₂(f_hi/f_lr) | A_fine / √log₂k |", "|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in LP.sort_values(["unit", "pair"]).itertuples(): L.append(f"| {r.unit} | {r.pair} | {r.n_tiles} | {r.A_fine_median_m:.4f} | {r.A_fine_p10_m:.4f}–{r.A_fine_p90_m:.4f} | {r.s_lr_median_m:.2f} | {r.k} | {r.lr_native_m:.1f} | {r.hr_res_m:.2f} | {r.log2k:.1f} | {r.oct_eff:.2f}{' (clipped)' if r.f_hi_clipped else ''} | {r.A_norm_median:.4f} |")
emit("level_per_pair", "level_geometry/level_per_pair.csv (level_geometry_r08.py)", L)
lab = dict(level_raw_vs_s_lr="median A_fine vs median s_lr (raw)", level_norm_vs_s_lr="A_fine / √log₂k vs median s_lr (band-normalised)", GBT_raw_vs_level_raw="GBT_ship unit median vs observed level (raw)", GBT_norm_vs_level_norm="GBT_ship / √log₂k vs A_fine / √log₂k (band-normalised)", k_vs_s_lr="k vs median s_lr", log2k_vs_level_raw="log₂ k vs median A_fine (raw)")
emit("level_correlations", "level_geometry/level_correlations.json (level_geometry_r08.py)", ["| cross-unit correlation (n = 16 units) | Spearman ρ [95 % bootstrap CI over units] |", "|---|---|"] + [f"| {lab[k]} | {v['rho']:+.3f} [{v['ci95'][0]:+.3f}, {v['ci95'][1]:+.3f}] |" for k, v in LC["correlations"].items()] + [f"| k range / lr_native range (m) | {LC['k_range']} / {LC['lr_native_range_m'][0]:.1f}–{LC['lr_native_range_m'][1]:.1f} |", f"| pairs with f_hi clipped at 0.45 (effective width < log₂ k) | {len(LC['pairs_with_f_hi_clipped'])}: {', '.join(LC['pairs_with_f_hi_clipped'])} |"])

# ---- §5 geometry
GU = pd.read_csv(f"{R8.OUT_LEVEL}/geometry_partial_rho_per_unit.csv"); GS = json.load(open(f"{R8.OUT_LEVEL}/geometry_summary.json"))
keys = [c for c in GU.columns if "|" in c]; tn = {"log_A_fine": "log A_fine (target)", "log_GBT_ship": "log GBT_ship", "log_V2_seedavg": "log V2 (seed-avg)"}; gn = {"xtrack_mean_128": "mean ship_xtrack_frac", "beam_angle_mean_128": "mean ship_beam_angle", "log_count_median_128": "median log ship_count"}
L = ["| unit | pairs | " + " | ".join(f"{tn[k.split('|')[0]]} \\| {gn[k.split('|')[1]]}" for k in keys) + " |", "|---|---|" + "---|" * len(keys)]
for r in GU.itertuples(): L.append(f"| {star(r.unit)} | {int(r.n_pairs)} | " + " | ".join(f(getattr(r, k.replace('|', '_')) if hasattr(r, k.replace('|', '_')) else GU.loc[r.Index, k], sign=True) for k in keys) + " |")
L.append("| **median [CI] over units** | | " + " | ".join(f"{GS['summary'][k]['value']:+.3f} [{GS['summary'][k]['ci95'][0]:+.3f}, {GS['summary'][k]['ci95'][1]:+.3f}] (n {GS['summary'][k]['n']})" for k in keys) + " |")
emit("geometry_per_unit", "level_geometry/geometry_partial_rho_per_unit.csv, geometry_summary.json (level_geometry_r08.py)", L)
L = ["| variable | acquisition feature | partial Spearman ρ given log s_lr, median over units [95 % CI] | n units |", "|---|---|---|---|"] + [f"| {tn[k.split('|')[0]]} | {gn[k.split('|')[1]]} | {GS['summary'][k]['value']:+.3f} [{GS['summary'][k]['ci95'][0]:+.3f}, {GS['summary'][k]['ci95'][1]:+.3f}] | {GS['summary'][k]['n']} |" for k in keys]
emit("geometry_summary", "level_geometry/geometry_summary.json:summary (level_geometry_r08.py)", L)

# ---- §6 wide window
WS = json.load(open(f"{R8.OUT_WIDE}/scores.json")); DF = pd.read_csv(f"{R8.OUT_WIDE}/defined_fraction.csv"); LT = json.load(open(f"{R8.OUT_WIDE}/leak_test.json")); PInfo = json.load(open(f"{R8.OUT_WIDE}/pairs_info.json"))
PW = pd.read_parquet(f"{R8.OUT_WIDE}/pred_tile_wide.parquet"); d128 = PW.groupby("unit").agg(**{c: (c, lambda s: float(np.isfinite(s).mean())) for c in ("s_lr_128", "C_128", "shat_fine_128", "beta_128")})
L = ["| unit | tiles | s_lr_W64 | s_lr_128 | C_W64 | C_128 | ŝ_fine_W64 | ŝ_fine_128 | β_W64 | β_128 |", "|---|---|---|---|---|---|---|---|---|---|"]
for r in DF.itertuples():
    g = d128.loc[r.unit] if r.unit in d128.index else None; v = (lambda c: f"{g[c]:.3f}" if g is not None else "—")
    L.append(f"| {star(r.unit) if r.unit != 'lu16' else 'lu16 (EW0207)'} | {r.n_tiles:,} | {r.s_lr_W64:.3f} | {v('s_lr_128')} | {r.C_W64:.3f} | {v('C_128')} | {r.shat_fine_W64:.3f} | {v('shat_fine_128')} | {r.beta_W64:.3f} | {v('beta_128')} |")
L.append("| **units with the row defined on ≥ 10 tiles of every pair (scored)** | | " + " | ".join(str(int(np.sum([np.isfinite(WS['scores_per_unit'][c][u]) for u in units]))) + " / 16" for c in ("s_lr_W64", "s_lr_128", "C_W64", "C_128", "shat_fine_W64", "shat_fine_128", "beta_W64", "beta_128")) + " |")
emit("wide_defined", "wide_window/defined_fraction.csv, pred_tile_wide.parquet, scores.json (wide_window_r08.py)", L)
cols = [c for pr in WS["pairs"] for c in pr] + WS["context_columns"]
L = ["| unit | " + " | ".join(cols) + " |", "|---|" + "---|" * len(cols)] + [f"| {star(u)} | " + " | ".join(f(WS['scores_per_unit'][c][u], sign=True) for c in cols) + " |" for u in units]
emit("wide_per_unit", "wide_window/scores.json:scores_per_unit (wide_window_r08.py)", L)
L = ["| row | 16 units: median ρ [CI] | 15 units (no lu08) |", "|---|---|---|"] + [f"| {c} | {ci(WS['median_ci']['all16'][c])} | {ci(WS['median_ci']['fifteen'][c])} |" for c in cols]
emit("wide_median", "wide_window/scores.json:median_ci (wide_window_r08.py)", L)
L = ["| comparison (W64 row − 128-px row) | 16 units: Δ median ρ [CI] | better / worse | p | 15 units (no lu08): Δ [CI] | better / worse | p |", "|---|---|---|---|---|---|---|"]
for w, n in WS["pairs"]:
    a = WS["comparisons"]["all16"][f"{w}-{n}"]; b = WS["comparisons"]["fifteen"][f"{w}-{n}"]; L.append(f"| {w} − {n} | {cmp(a)} | {cmp(b)} |")
for w, _ in WS["pairs"]:
    for c in ("ref_s_lr", "GBT_ship_A_fine", "V2_seedavg"):
        a = WS["comparisons"]["all16"][f"{w}-{c}"]; b = WS["comparisons"]["fifteen"][f"{w}-{c}"]; L.append(f"| {w} − {c} | {cmp(a)} | {cmp(b)} |")
emit("wide_comparisons", "wide_window/scores.json:comparisons (wide_window_r08.py)", L)
nan_pairs = sorted({p["pair"] for p in PInfo["pairs"] if not p["crs_equal"]})
emit("wide_checks", "wide_window/leak_test.json, pairs_info.json (wide_window_r08.py)", ["| item | value |", "|---|---|", f"| leak test: tiles identical with the HR keys replaced by noise | {LT['n_identical']} / {LT['n']} |", f"| pairs whose context files matched SHA256SUMS and the parquet hashes | {sum(all(v['ok'] for v in p['verification'].values()) for p in PInfo['pairs'])} / {len(PInfo['pairs'])} |", f"| pairs whose tile CRS differs from the context CRS (coordinates transformed) | {len(nan_pairs)}{': ' + ', '.join(nan_pairs) if nan_pairs else ''} |", f"| window | {PInfo['W_cells']} × {PInfo['W_cells']} context cells centred on the tile centre; < {int(PInfo['min_valid_frac']*100)} % valid → NaN |"])

# ---- ledger of failures and exclusions
L = ["| stage | item | count | reason |", "|---|---|---|---|", f"| §1 within-site | infeasible pairs | {len(fe['infeasible'])} of 38 | feasibility rule (tiles / blocks / training tiles after the buffer); see the infeasible table |",
     f"| §1 within-site | units with no feasible pair | {len(fe['units_without_feasible_pair'])} of 16 | {', '.join(fe['units_without_feasible_pair'])} |",
     f"| §2 permutation | permutations with undefined ρ | {int((PI.n_perm < R8.N_PERM).sum())} of {len(PI)} unit × group cells | — |",
     f"| §3 fields | pairs whose shown subwindow is below the 0.9 valid-fraction target | {int((FM.subwindow & (FM.window_valid_frac < R8.SUBWIN_VALID_FRAC)).sum())} of 39 | no square between 1 and 2 km at the centroid reached 0.9 valid (narrow or sparse coverage); the best square is shown: {', '.join(f'{r.pair} ({r.window_valid_frac:.2f})' for r in FM[FM.subwindow & (FM.window_valid_frac < R8.SUBWIN_VALID_FRAC)].itertuples())} |",
     f"| §5 geometry | units without xtrack | 1 of 12 | vu02 (EX1402L2 ship_xtrack_frac unavailable, R05 override) |",
     f"| §6 wide window | tiles with < 50 % valid context cells (s_lr_W64 undefined) | {int(round((1 - np.average(DF.s_lr_W64, weights=DF.n_tiles)) * DF.n_tiles.sum()))} of {DF.n_tiles.sum():,} | window partly outside the context grid or over invalid cells |",
     f"| §6 wide window | leak test | {LT['n'] - LT['n_identical']} failures of {LT['n']} | — |"]
emit("ledger", "within_site/feasibility.json, importance/permutation_importance.csv, fields/field_metrics.csv, wide_window/defined_fraction.csv, leak_test.json", L)
json.dump(SRC, open(f"{TAB}/sources.json", "w"), indent=1); print("wrote tables/sources.json")
